package com.mindarray.store;

import com.mindarray.GlobalConstants;
import com.mindarray.api.AIOpsObject;
import com.mindarray.api.CorrectionProfile;
import com.mindarray.db.DBConstants;
import com.mindarray.util.Logger;

import java.util.List;
import java.util.Map;

import static com.mindarray.api.APIConstants.*;

public class BusinessHourConfigStore extends AbstractConfigStore {
    private static final Logger LOGGER = new Logger(BusinessHourConfigStore.class, GlobalConstants.MOTADATA_STORE, "Business Hour Config Store");
    private static final BusinessHourConfigStore STORE = new BusinessHourConfigStore();

    private BusinessHourConfigStore() {
        super(DBConstants.TBL_BUSINESS_HOUR, LOGGER, false,
                List.of(
                        Map.of(
                                REFERENCE_ENTITY, Entity.OBJECT,
                                REFERENCE_ENTITY_PROPERTY, AIOpsObject.OBJECT_BUSINESS_HOUR_PROFILE,
                                REFERENCE_ENTITY_STORE, ConfigStore.OBJECT,
                                REFERENCE_ENTITY_PROPERTY_TYPE, ReferenceEntityPropertyType.VALUE
                        ),
                        Map.of(
                                REFERENCE_ENTITY, Entity.CORRECTION_PROFILE,
                                REFERENCE_ENTITY_PROPERTY, CorrectionProfile.CORRECTION_PROFILE_CONTEXT,
                                REFERENCE_ENTITY_NESTED_PROPERTY, CorrectionProfile.BUSINESS_HOUR_PROFILE,
                                REFERENCE_ENTITY_STORE, ConfigStore.CORRECTION_PROFILE,
                                REFERENCE_ENTITY_PROPERTY_TYPE, ReferenceEntityPropertyType.MULTIMAP_VALUE
                        )
                )
        );
    }

    public static BusinessHourConfigStore getStore() {
        return STORE;
    }
}
